ST.xhtml:p:
RY2Trigger(CLK := g_biY2AbsExecute OR bY2AbsEXecute OR g_bY2AbsExecute);

IF RY2Trigger.Q THEN
  nY2AbsState := 1;
  g_boY2AbsDone := FALSE;
  g_bY2AbsDone := FALSE;
  bY2AbsDone := FALSE;
  IF g_biY2AbsExecute THEN
    dY2TargetPos := g_fiY2AbsPosition; 
    dY2TargetVel := g_fiY2AbsVelocity;
  ELSIF bY2AbsEXecute THEN
    dY2TargetPos := dY2AbsPosition;
    dY2TargetVel := 0.0;
  ELSE
    dY2TargetPos := g_fY2AbsPosition;
    dY2TargetVel := g_fY2AbsVelocity;
  END_IF;
  IF dY2TargetVel = 0.0 THEN
    dY2TargetVel := dY2AbsVelocity;
  END_IF;
END_IF;

IF NOT(g_biY2AbsExecute OR bY2AbsEXecute OR g_bY2AbsExecute) THEN
  g_boY2AbsDone := FALSE;
  g_bY2AbsDone := FALSE;
  bY2AbsDone := FALSE;
END_IF;

CASE nY2AbsState OF
  0:
    nY2AbsState := 0;
  1:
    g_Y2MoveAbs.Execute := TRUE;
    g_Y2MoveAbs.Velocity := dY2TargetVel;
    g_Y2MoveAbs.Position := dY2TargetPos;
    IF g_Y2MoveAbs.Done THEN
      g_Y2MoveAbs.Execute := FALSE;
      g_boY2AbsDone := TRUE;
      g_bY2AbsDone := TRUE;
      bY2AbsDone := TRUE;
      nY2AbsState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nY2AbsState := 20;
    END_IF;
    IF g_Y2MoveAbs.CommandAborted OR g_Y2MoveAbs.Error THEN
      g_Y2MoveAbs.Execute := FALSE;
      g_boY2AbsDone := FALSE;
      nY2AbsState := 0;
    END_IF;
  20:
    g_Y2MoveAbs.Execute := FALSE;
    g_Y2MoveStop.Execute := TRUE;
    IF g_Y2MoveStop.Done AND g_bPlcStartBuffer THEN
      g_Y2MoveStop.Execute := FALSE;
      nY2AbsState := 1;
    END_IF;
    IF g_Y2MoveStop.CommandAborted OR g_Y2MoveStop.Error THEN
      g_Y2MoveStop.Execute := FALSE;
      nY2AbsState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nY2AbsState := 0;
  g_Y2MoveAbs.Execute := FALSE;
  g_Y2MoveStop.Execute := FALSE;

  nY3AbsState := 0;
  g_Y3MoveAbs.Execute := FALSE;
  g_Y3MoveStop.Execute := FALSE;
END_IF;


RY3Trigger(CLK := g_biY3AbsExecute OR bY3AbsEXecute OR g_bY3AbsExecute);

IF RY3Trigger.Q THEN
  nY3AbsState := 1;
  g_boY3AbsDone := FALSE;
  g_bY3AbsDone := FALSE;
  bY3AbsDone := FALSE;
  IF g_biY3AbsExecute THEN
    dY3TargetPos := g_fiY3AbsPosition; 
    dY3TargetVel := g_fiY3AbsVelocity;
  ELSIF bY3AbsEXecute THEN
    dY3TargetPos := dY3AbsPosition;
    dY3TargetVel := 0.0;
  ELSE
    dY3TargetPos := g_fY3AbsPosition;
    dY3TargetVel := g_fY3AbsVelocity;
  END_IF;
  IF dY3TargetVel = 0.0 THEN
    dY3TargetVel := dY3AbsVelocity;
  END_IF;
END_IF;

IF NOT(g_biY3AbsExecute OR bY3AbsEXecute OR g_bY3AbsExecute) THEN
  g_boY3AbsDone := FALSE;
  g_bY3AbsDone := FALSE;
  bY3AbsDone := FALSE;
END_IF;

CASE nY3AbsState OF
  0:
    nY3AbsState := 0;
  1:
    g_Y3MoveAbs.Execute := TRUE;
    g_Y3MoveAbs.Velocity := dY3TargetVel;
    g_Y3MoveAbs.Position := dY3TargetPos;
    IF g_Y3MoveAbs.Done THEN
      g_Y3MoveAbs.Execute := FALSE;
      g_boY3AbsDone := TRUE;
      g_bY3AbsDone := TRUE;
      bY3AbsDone := TRUE;
      nY3AbsState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nY3AbsState := 20;
    END_IF;
    IF g_Y3MoveAbs.CommandAborted OR g_Y3MoveAbs.Error THEN
      g_Y3MoveAbs.Execute := FALSE;
      g_boY3AbsDone := FALSE;
      nY3AbsState := 0;
    END_IF;
  20:
    g_Y3MoveAbs.Execute := FALSE;
    g_Y3MoveStop.Execute := TRUE;
    IF g_Y3MoveStop.Done AND g_bPlcStartBuffer THEN
      g_Y3MoveStop.Execute := FALSE;
      nY3AbsState := 1;
    END_IF;
    IF g_Y3MoveStop.CommandAborted OR g_Y3MoveStop.Error THEN
      g_Y3MoveStop.Execute := FALSE;
      nY3AbsState := 0;
    END_IF;
END_CASE;
